def transform(grid):
    """Color a 3x3 neighborhood around each 2 marker inside a 3-object's bbox."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the bounding boxes of the rectangular color-3 panels. Markers inside
    # these panels trigger a 3x3 patch, while nearby external markers do not.
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            boxes.append((min(x for x, y in cells), max(x for x, y in cells),
                          min(y for x, y in cells), max(y for x, y in cells)))

    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1
                                       for r0, r1, c0, c1 in boxes):
                centers.append((r, c))

    for r, c in centers:
        for rr in range(max(0, r-1), min(h, r+2)):
            for cc in range(max(0, c-1), min(w, c+2)):
                if grid[rr][cc] != 2:
                    out[rr][cc] = 1
    return out
